sql_query:
SELECT SUM(gross_revenue_usd) as total_revenue
FROM royalties
WHERE quarter = 'Q4-2024';

SELECT 
    ROUND(100.0 * SUM(CASE WHEN is_active = false THEN 1 ELSE 0 END) / COUNT(*), 2) as inactive_percentage
FROM artists;

SELECT COUNT(DISTINCT user_id) as unique_spotify_users
FROM playlists
WHERE platform = 'Spotify';
